def _mentioned(source, name):
    return re.search(r"\b" + re.escape(name) + r"\b", source) is not None


def _callbacks(source):
    """Give kuna's generic void-pointer callbacks an callable C type."""
    # Locals and arguments are commonly typed void * even when every use is a
    # call.  An unprototyped function pointer retains the recovered calling
    # sequence while making the expression legal C.
    called = set(re.findall(r"\(\*\s*([A-Za-z_]\w*)\s*\)\s*\(", source))
    for name in called:
        source = re.sub(
            r"\(\*\s*" + re.escape(name) + r"\s*\)\s*\(",
            "((long (*)())" + name + ")(", source)
    # Direct calls through a pointer loaded from memory are emitted as
    # (**(void **)address)(...).  Only the pointee spelling needs correction.
    source = re.sub(r"\*\*\s*\(\s*void\s*\*\s*\*\s*\)",
                    "**(code **)", source)
    source = source.replace("(*(void *)", "((long (*)())")
    return source


