def _byte_slices(source):
    """Translate Ghidra-style ``object._offset_size_`` byte lvalues."""
    pattern = re.compile(r"\b([A-Za-z_]\w*(?:\[[^\]]+\])?)\._(\d+)_(\d+)_")
    pointer_vars = set(re.findall(
        r"(?m)^\s*(?:(?:unsigned|signed)\s+)?(?:char|short|int|long|void|"
        r"int[1248]|uint[1248])\s*\*+\s*([A-Za-z_]\w*)\s*(?:;|//)",
        source))
    pointer_fields = set()
    for var in pointer_vars:
        pointer_fields.update(
            (m.group(1), m.group(2), m.group(3))
            for m in re.finditer(r"\b" + re.escape(var)
                                 + r"\s*=\s*([A-Za-z_]\w*)\._(\d+)_(\d+)_",
                                 source))
    pointer_fields.update(
        (m.group(1), m.group(2), m.group(3))
        for m in re.finditer(
            r"\(\s*(?:[A-Za-z_]\w*\s+)*[A-Za-z_]\w*\s*\*+\s*\)\s*"
            r"([A-Za-z_]\w*)\._(\d+)_(\d+)_", source))
    # A leading unary star likewise says that the stored word is a pointer.
    # Require unary-expression punctuation (or a scalar cast), so an ordinary
    # multiplication by a sliced integer is not misclassified.
    unary_slice = (r"([A-Za-z_]\w*)\._(\d+)_(\d+)_")
    pointer_fields.update(
        (m.group(1), m.group(2), m.group(3))
        for m in re.finditer(
            r"(?:^|[=(:,!~?;{}\[+\-/%&|^<>])\s*\*\s*" + unary_slice,
            source, re.MULTILINE))
    pointer_fields.update(
        (m.group(1), m.group(2), m.group(3))
        for m in re.finditer(
            r"\(\s*(?:(?:unsigned|signed)\s+)?[A-Za-z_]\w*"
            r"(?:\s+[A-Za-z_]\w*)*\s*\)\s*\*\s*" + unary_slice,
            source))
    indexed_fields = set(
        (m.group(1), m.group(2), m.group(3))
        for m in re.finditer(
            r"\b([A-Za-z_]\w*)\._(\d+)_(\d+)_\s*\[", source))

    def replace(match):
        ctype = _SLICE_TYPES.get(match.group(3))
        if ctype is None:
            return match.group(0)
        key = (match.group(1), match.group(2), match.group(3))
        following = source[match.end():].lstrip()
        if key in indexed_fields or following.startswith("["):
            ctype = "unsigned char *"
        elif key in pointer_fields:
            ctype = "unsigned long *"
        elif following.startswith("("):
            ctype = "code *"
        return ("(*(" + ctype + " *)((unsigned char *)&" + match.group(1)
                + " + " + match.group(2) + "))")

    return pattern.sub(replace, source)


