def _pointer_float_casts(source):
    pointers = set(re.findall(
        r"(?m)^\s*(?:(?:unsigned|signed)\s+)?(?:char|short|int|long|void|"
        r"int[1248]|uint[1248])\s*\*+\s*([A-Za-z_]\w*)\s*(?:;|//)",
        source))
    for name in pointers:
        source = re.sub(r"\((float|double|long double)\)\s*" + re.escape(name)
                        + r"\b", r"(\1)(long)" + name, source)
    return source


